CREATE TABLE IF NOT EXISTS orgs (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    sport TEXT NOT NULL DEFAULT 'baseball',
    campus_label TEXT,
    campus_lat REAL,
    campus_lng REAL,
    is_demo INTEGER NOT NULL DEFAULT 0,
    settings_json TEXT NOT NULL DEFAULT '{}',
    created_at TEXT NOT NULL
  );

CREATE TABLE IF NOT EXISTS users (
    id TEXT PRIMARY KEY,
    org_id TEXT NOT NULL REFERENCES orgs(id),
    email TEXT NOT NULL UNIQUE,
    name TEXT NOT NULL,
    title TEXT,
    role TEXT NOT NULL,
    password_hash TEXT NOT NULL,
    is_shared INTEGER NOT NULL DEFAULT 0,
    last_brief_at TEXT,
    created_at TEXT NOT NULL
  );

CREATE TABLE IF NOT EXISTS sessions (
    id TEXT PRIMARY KEY,
    user_id TEXT NOT NULL REFERENCES users(id),
    acting_user_id TEXT,
    expires_at TEXT NOT NULL,
    created_at TEXT NOT NULL
  );

CREATE TABLE IF NOT EXISTS sources (
    id TEXT PRIMARY KEY,
    org_id TEXT NOT NULL REFERENCES orgs(id),
    provider_id TEXT NOT NULL,
    name TEXT NOT NULL,
    kind TEXT NOT NULL,
    status TEXT NOT NULL,
    status_detail TEXT,
    attested_by TEXT,
    last_checked_at TEXT,
    config_json TEXT NOT NULL DEFAULT '{}',
    created_at TEXT NOT NULL
  );

CREATE TABLE IF NOT EXISTS athletes (
    id TEXT PRIMARY KEY,
    org_id TEXT NOT NULL REFERENCES orgs(id),
    first_name TEXT NOT NULL,
    last_name TEXT NOT NULL,
    grad_year INTEGER,
    sport TEXT NOT NULL,
    primary_position TEXT,
    secondary_position TEXT,
    bats TEXT,
    throws TEXT,
    high_school TEXT,
    team TEXT,
    city TEXT,
    state TEXT,
    zip TEXT,
    lat REAL,
    lng REAL,
    geo_precision TEXT,
    identity_confidence REAL NOT NULL DEFAULT 1,
    commitment_status TEXT NOT NULL DEFAULT 'unknown',
    commitment_verified INTEGER NOT NULL DEFAULT 0,
    commitment_source_id TEXT,
    email TEXT,
    guardian_email TEXT,
    phone TEXT,
    x_handle TEXT,
    contact_consent TEXT NOT NULL DEFAULT 'unknown',
    is_minor INTEGER,
    opted_out INTEGER NOT NULL DEFAULT 0,
    is_demo INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
  );

CREATE INDEX IF NOT EXISTS idx_athletes_org ON athletes(org_id, grad_year);

CREATE TABLE IF NOT EXISTS athlete_source_records (
    id TEXT PRIMARY KEY,
    org_id TEXT NOT NULL,
    athlete_id TEXT NOT NULL REFERENCES athletes(id),
    source_id TEXT NOT NULL REFERENCES sources(id),
    external_id TEXT,
    raw_json TEXT NOT NULL,
    match_confidence REAL NOT NULL,
    match_reason TEXT,
    fetched_at TEXT NOT NULL
  );

CREATE INDEX IF NOT EXISTS idx_asr_ext ON athlete_source_records(org_id, source_id, external_id);

CREATE TABLE IF NOT EXISTS metric_observations (
    id TEXT PRIMARY KEY,
    org_id TEXT NOT NULL,
    athlete_id TEXT NOT NULL REFERENCES athletes(id),
    source_id TEXT NOT NULL REFERENCES sources(id),
    metric_key TEXT NOT NULL,
    value REAL NOT NULL,
    unit TEXT NOT NULL,
    measured_at TEXT,
    checked_at TEXT NOT NULL,
    verification TEXT NOT NULL,
    source_url TEXT,
    event_name TEXT,
    created_at TEXT NOT NULL
  );

CREATE INDEX IF NOT EXISTS idx_obs_athlete ON metric_observations(org_id, athlete_id, metric_key);

CREATE TABLE IF NOT EXISTS film_links (
    id TEXT PRIMARY KEY,
    org_id TEXT NOT NULL,
    athlete_id TEXT NOT NULL REFERENCES athletes(id),
    source_id TEXT NOT NULL REFERENCES sources(id),
    url TEXT NOT NULL,
    title TEXT,
    recorded_at TEXT,
    checked_at TEXT NOT NULL
  );

CREATE TABLE IF NOT EXISTS games (
    id TEXT PRIMARY KEY,
